func nativeLab(t *testing.T) *Lab {
	t.Helper()
	root := t.TempDir()
	l := &Lab{Ctx: t.Context(), Root: root, Logs: filepath.Join(root, "logs"), Stage: filepath.Join(root, "stage"), Secrets: filepath.Join(root, "secrets"), Images: filepath.Join(root, "images"), Binary: "unused", OperatorConfig: "config", Bridge: "tsfabc123b", Addresses: map[string]string{"host": "198.19.7.14", "c1": "198.19.7.11", "c2": "198.19.7.12", "c3": "198.19.7.13"}, VMs: map[string]*VM{}}
	l.Subnet = netip.MustParsePrefix("198.19.7.0/24")
	l.defaults()
	for _, d := range []string{l.Logs, l.Stage, l.Secrets, l.Images} {
		if e := os.Mkdir(d, 0o700); e != nil {
			t.Fatal(e)
		}
	}
	return l
}
func marshal(v any) string {
	b, e := json.Marshal(v, json.Deterministic(true))
	if e != nil {
		panic(e)
	}
	return string(b)
}
func requireError(t *testing.T, e error, part string) {
	t.Helper()
	if e == nil || !strings.Contains(e.Error(), part) {
		t.Fatalf("got %v, want error containing %q", e, part)
	}
}
func requireEqual(t *testing.T, a, b any) {
	t.Helper()
	if !reflect.DeepEqual(a, b) && !jsonEqual(a, b) {
		t.Fatalf("got %#v, want %#v", a, b)
	}
}

func (l *Lab) defaults() {
	if l.Ctx == nil {
		l.Ctx = context.Background()
	}
	if l.Command == nil {
		l.Command = Execute
	}
	if l.Stdout == nil {
		l.Stdout = io.Discard
	}
	if l.Now == nil {
		l.Now = time.Now
	}
	if l.MonotonicNS == nil {
		base := time.Now()
		l.MonotonicNS = func() int64 { return time.Since(base).Nanoseconds() }
	}
	if l.Sleep == nil {
		l.Sleep = time.Sleep
	}
	if l.startProcess == nil {
		l.startProcess = Start
	}
	if l.lstat == nil {
		l.lstat = os.Lstat
	}
	if l.HostDiagnostics == nil {
		l.HostDiagnostics = map[string]bool{}
	}
	if l.ClockDiagnostics == nil {
		l.ClockDiagnostics = map[string]bool{}
	}
	if l.GuestClockUpperNS == nil {
		l.GuestClockUpperNS = map[string]int64{}
	}
}

func (l *Lab) cmd(argv []string, o CommandOptions) (CommandResult, error) {
	l.defaults()
	if o.Dir == "" {
		o.Dir = l.Options.SourceRoot
	}
	r, e := l.Command(l.Ctx, argv, o)
	if pending, ok := errors.AsType[*PendingCommandError](e); ok && !slices.Contains(l.PendingCommands, pending.Process) {
		l.PendingCommands = append(l.PendingCommands, pending.Process)
	}
	return r, e
}
func (l *Lab) sudo(args ...string) (CommandResult, error) {
	return l.cmd(append([]string{"sudo", "-n"}, args...), CommandOptions{})
}
func (l *Lab) sudoAllow(args ...string) (CommandResult, error) {
	return l.cmd(append([]string{"sudo", "-n"}, args...), CommandOptions{AllowFailure: true})
}
func (l *Lab) Note(event string, fields Object) {
	l.defaults()
	entry := Object{"time": l.Now().UTC().Format(time.RFC3339), "event": event}
	for k, v := range fields {
		entry[k] = v
	}
	l.Events = append(l.Events, entry)
	_ = writeJSON(filepath.Join(l.Logs, "events.json"), l.Events)
	b, _ := json.Marshal(entry)
	fmt.Fprintln(l.Stdout, string(b))
}

func CuratedHostStatuses(statuses any, captured time.Time) ([]Object, error) {
	rows, ok := statuses.([]any)
	if !ok {
		return nil, errors.New("operator hosts did not return a list")
	}
	result := []Object{}
	for _, raw := range rows {
		s, ok := raw.(map[string]any)
		if !ok {
			return nil, errors.New("operator hosts returned an invalid status")
		}
		r, ok := s["registration"].(map[string]any)
		if !ok {
			return nil, errors.New("operator hosts returned an invalid status")
		}
		expiry, _ := time.Parse(time.RFC3339Nano, str(s["session_expires_at"]))
		capacity := object(r["capacity"])
		reports := []Object{}
		for _, rawReport := range array(s["reports"]) {
			report, ok := rawReport.(map[string]any)
			if !ok {
				continue
			}
			var h any
			if id, ok := report["session_id"].(string); ok {
				h = head(hashBytes([]byte(id)), 32)
			}
			reports = append(reports, Object{"role": report["role"], "generation": report["generation"], "state": report["state"], "digest_prefix": head(str(report["digest"]), 12), "epoch": report["epoch"], "observed_at": report["observed_at"], "session_id_hash": h})
		}
		result = append(result, Object{"node": r["node"], "environment": r["environment"], "roles": r["roles"], "registration_generation": r["generation"], "capacity": Object{"cpu": capacity["cpu"], "memory_bytes": capacity["memory_bytes"], "disk_bytes": capacity["disk_bytes"]}, "session_expires_at": s["session_expires_at"], "session_current": expiry.After(captured), "verified": s["verified"], "reports": reports})
	}
	return result, nil
}
func (l *Lab) Operator(operation string, timeout time.Duration, allow bool, stage string, args ...string) (any, error) {
	l.defaults()
	if stage == "" {
		stage = operation
	}
	started := l.Now()
	argv := append([]string{l.Binary, "operator", operation, "--config", l.OperatorConfig}, args...)
	r, e := l.cmd(argv, CommandOptions{Timeout: timeout, AllowFailure: true})
	fields := Object{"operation": operation, "stage": stage, "exit_code": r.Code, "elapsed_seconds": l.Now().Sub(started).Seconds(), "timeout_seconds": timeout.Seconds(), "stdout": "", "stderr": tail(strings.TrimSpace(r.Stderr), 1000), "failure": nil}
	if e != nil {
		fields["exit_code"] = nil
		fields["failure"] = "launch_error"
		if errors.Is(e, context.DeadlineExceeded) {
			fields["failure"] = "subprocess_timeout"
		}
		l.Note("operator", fields)
		return nil, e
	}
	logged := tail(strings.TrimSpace(r.Stdout), 3000)
	if operation == "hosts" {
		logged = ""
		if r.Code == 0 {
			v, e := decode(r.Stdout)
			if e == nil {
				curated, e := CuratedHostStatuses(v, l.Now())
				if e == nil {
					b, _ := json.Marshal(curated)
					logged = tail(string(b), 3000)
				} else {
					logged = "<invalid host-status output>"
				}
			} else {
				logged = "<invalid host-status output>"
			}
		}
	}
	fields["stdout"] = logged
	if r.Code != 0 {
		fields["failure"] = "exit_nonzero"
	}
	l.Note("operator", fields)
	if r.Code != 0 {
		if allow {
			return nil, nil
		}
		out := r.Stdout
		if operation == "hosts" {
			out = ""
		}
		return nil, fmt.Errorf("command %q failed (%d): %s %s", argv, r.Code, tail(out, 2000), tail(r.Stderr, 2000))
	}
	return decode(r.Stdout)
}
func (l *Lab) HostSession(version string, timeout time.Duration, stage string) (Object, error) {
	v, e := l.Operator("hosts", timeout, false, stage)
	if e != nil {
		return nil, e
	}
	rows := array(v)
	if len(rows) != 1 {
		return nil, errors.New("expected exactly one host status")
	}
	s := object(rows[0])
	expiry, e := time.Parse(time.RFC3339Nano, str(s["session_expires_at"]))
	if e != nil {
		return nil, errors.New("host status lacks a session expiry")
	}
	if !expiry.After(l.Now()) {
		return nil, errors.New("host session is not current")
	}
	generation := int64(2)
	if version == "v1" {
		generation = 1
	}
	reports := []Object{}
	for _, r := range array(s["reports"]) {
		r := object(r)
		if r["role"] == "terrabase" && r["state"] == "running" && integer(r["generation"]) == generation {
			reports = append(reports, r)
		}
	}
	if len(reports) != 1 || str(reports[0]["session_id"]) == "" {
		return nil, errors.New("host lacks a unique running report bound to a session")
	}
	return Object{"expires_at": expiry, "session_id": reports[0]["session_id"], "report": reports[0], "reader_verified": s["verified"]}, nil
}

func (l *Lab) CaptureHostStatus(label string) {
	l.defaults()
	if l.HostDiagnostics[label] {
		return
	}
	l.HostDiagnostics[label] = true
	captured := l.Now()
	snapshot := Object{"captured_at": captured, "label": label}
	r, e := l.cmd([]string{l.Binary, "operator", "hosts", "--config", l.OperatorConfig}, CommandOptions{Timeout: 10 * time.Second, AllowFailure: true})
	if errors.Is(e, contextDeadline) {
		snapshot["status"] = "timeout"
	} else if e != nil {
		snapshot["status"] = "error"
		snapshot["error_type"] = fmt.Sprintf("%T", e)
	} else if r.Code != 0 {
		snapshot["status"] = "operator_failed"
		snapshot["exit_code"] = r.Code
	} else {
		v, e := decode(r.Stdout)
		hosts, ce := CuratedHostStatuses(v, captured)
		if e != nil || ce != nil {
			snapshot["status"] = "error"
		} else {
			snapshot["status"] = "ok"
			snapshot["hosts"] = hosts
		}
	}
	path := filepath.Join(l.Logs, "host-status-"+label+".json")
	if e = writeJSON(path, snapshot); e != nil {
		l.Note("host_status_diagnostics", Object{"label": label, "status": "write_failed", "error_type": fmt.Sprintf("%T", e)})
		return
	}
	l.Note("host_status_diagnostics", Object{"label": label, "path": path, "status": snapshot["status"]})
}

func writeJSON(path string, v any) error {
	b, e := json.Marshal(v, json.Deterministic(true))
	if e != nil {
		return e
	}
	if e = os.MkdirAll(filepath.Dir(path), 0o700); e != nil {
		return e
	}
	return os.WriteFile(path, append(b, '\n'), 0o600)
}
func decode(s string) (any, error) { var v any; e := json.Unmarshal([]byte(s), &v); return v, e }
func readObject(path string) (Object, error) {
	b, e := os.ReadFile(path)
	if e != nil {
		return nil, e
	}
	v, e := decode(string(b))
	if e != nil {
		return nil, e
	}
	m, ok := v.(map[string]any)
	if !ok {
		return nil, fmt.Errorf("%s must contain a JSON object", path)
	}
	return m, nil
}

func waitCommand(ctx context.Context, p *Process, timeout time.Duration) error {
	if timeout <= 0 {
		timeout = 120 * time.Second
	}
	ctx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	for {
		if err := ctx.Err(); err != nil {
			return err
		}
		done, err := p.Exited()
		if err != nil || done {
			return err
		}
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-time.After(25 * time.Millisecond):
		}
	}
}

func Execute(ctx context.Context, argv []string, o CommandOptions) (CommandResult, error) {
	if len(argv) == 0 {
		return CommandResult{}, errors.New("empty command")
	}
	if err := ctx.Err(); err != nil {
		return CommandResult{}, err
	}
	c := exec.Command(argv[0], argv[1:]...)
	c.Dir = o.Dir
	c.Env = o.Env
	c.Stdin = strings.NewReader(o.Input)
	c.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	c.WaitDelay = 2 * time.Second
	var out, errout commandBuffer
	c.Stdout = &out
	c.Stderr = &errout
	if err := c.Start(); err != nil {
		return CommandResult{}, err
	}
	p := &Process{Cmd: c}
	err := errors.Join(waitCommand(ctx, p, o.Timeout), p.Stop(10*time.Second, true))
	r := CommandResult{Stdout: out.String(), Stderr: errout.String()}
	r.Code = p.ExitCode
	if !p.Reaped {
		return r, &PendingCommandError{Process: p, Err: err}
	}
	if err != nil {
		return r, err
	}
	if r.Code != 0 && !o.AllowFailure {
		return r, fmt.Errorf("command %q failed (%d): %s %s", argv, r.Code, tail(r.Stdout, 2000), tail(r.Stderr, 2000))
	}
	return r, nil
}

func Start(argv []string, dir string, output io.Writer) (*Process, error) {
	if len(argv) == 0 {
		return nil, errors.New("empty command")
	}
	c := exec.Command(argv[0], argv[1:]...)
	c.Dir = dir
	c.Stdout = output
	c.Stderr = output
	c.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	c.WaitDelay = 2 * time.Second
	if e := c.Start(); e != nil {
		return nil, e
	}
	return &Process{Cmd: c}, nil
}
func (p *Process) PID() int { return p.Cmd.Process.Pid }
func (p *Process) Exited() (bool, error) {
	if p.Reaped {
		return true, nil
	}
	if p.hooks != nil && p.hooks.exited != nil {
		return p.hooks.exited()
	}
	var info unix.Siginfo
	e := unix.Waitid(unix.P_PID, p.PID(), &info, unix.WEXITED|unix.WNOHANG|unix.WNOWAIT, nil)
	if e != nil {
		return false, fmt.Errorf("owned process %d was reaped before cleanup: %w", p.PID(), e)
	}
	return info.Signo != 0, nil
}
func (p *Process) Group() (int, error) {
	if p.Reaped {
		return 0, fmt.Errorf("owned process %d was reaped before group cleanup", p.PID())
	}
	group := syscall.Getpgid
	if p.hooks != nil && p.hooks.group != nil {
		group = p.hooks.group
	}
	id, e := group(p.PID())
	if e != nil {
		return 0, e
	}
	if id != p.PID() {
		return 0, fmt.Errorf("owned process %d is no longer its process-group leader", p.PID())
	}
	return id, nil
}

func LiveProcessGroupMembers(pgid int) ([]int, error) {
	entries, e := os.ReadDir("/proc")
	if e != nil {
		return nil, e
	}
	members := []int{}
	for _, entry := range entries {
		pid, e := strconv.Atoi(entry.Name())
		if e != nil {
			continue
		}
		b, e := os.ReadFile(filepath.Join("/proc", entry.Name(), "stat"))
		if processStatGone(e) {
			continue
		}
		if e != nil {
			return nil, e
		}
		_, after, ok := strings.CutLast(string(b), ")")
		if !ok {
			return nil, fmt.Errorf("invalid process status for %d", pid)
		}
		f := strings.Fields(after)
		if len(f) < 3 {
			return nil, fmt.Errorf("invalid process status for %d", pid)
		}
		id, e := strconv.Atoi(f[2])
		if e != nil {
			return nil, e
		}
		if id == pgid && !slices.Contains([]string{"Z", "X", "x"}, f[0]) {
			members = append(members, pid)
		}
	}
	return members, nil
}

// A process can disappear after its stat file opens, returning ESRCH instead of ENOENT.
func processStatGone(err error) bool {
	return errors.Is(err, os.ErrNotExist) || errors.Is(err, syscall.ESRCH)
}

func WaitProcessGroupQuiescent(pgid int, timeout time.Duration) error {
	deadline := time.Now().Add(timeout)
	for {
		members, e := LiveProcessGroupMembers(pgid)
		if e != nil {
			return e
		}
		if len(members) == 0 {
			return nil
		}
		if time.Now().After(deadline) {
			return fmt.Errorf("owned process group %d still has live members: %v", pgid, members)
		}
		time.Sleep(50 * time.Millisecond)
	}
}
func (p *Process) WaitUnreaped(timeout time.Duration) (bool, error) {
	if p.hooks != nil && p.hooks.wait != nil {
		return p.hooks.wait(timeout)
	}
	deadline := time.Now().Add(timeout)
	for {
		done, e := p.Exited()
		if e != nil || done {
			return done, e
		}
		if time.Now().After(deadline) {
			return false, nil
		}
		time.Sleep(50 * time.Millisecond)
	}
}

func (p *Process) Stop(timeout time.Duration, kill bool) error {
	id, e := p.Group()
	if e != nil {
		return e
	}
	if !kill {
		if e = p.signalGroup(id, syscall.SIGTERM); e != nil && !errors.Is(e, syscall.ESRCH) {
			return e
		}
		if _, e = p.WaitUnreaped(timeout); e != nil {
			return e
		}
		if _, e = p.Group(); e != nil {
			return e
		}
	}
	if e = p.signalGroup(id, syscall.SIGKILL); e != nil && !errors.Is(e, syscall.ESRCH) {
		return e
	}
	quiescent := WaitProcessGroupQuiescent
	if p.hooks != nil && p.hooks.quiescent != nil {
		quiescent = p.hooks.quiescent
	}
	if e = quiescent(id, timeout); e != nil {
		return e
	}
	if p.hooks != nil && p.hooks.reap != nil {
		e = p.hooks.reap()
	} else {
		e = p.Cmd.Wait()
	}
	p.Reaped = true
	if p.Cmd.ProcessState != nil {
		p.ExitCode = p.Cmd.ProcessState.ExitCode()
	}
	if _, ok := errors.AsType[*exec.ExitError](e); ok {
		e = nil
	}
	if p.Output != nil {
		e = errors.Join(e, p.Output.Close())
		p.Output = nil
	}
	return e
}
func (p *Process) signalGroup(id int, signal syscall.Signal) error {
	if p.hooks != nil && p.hooks.signal != nil {
		return p.hooks.signal(id, signal)
	}
	return syscall.Kill(-id, signal)
}

func fixtureProcess() *Process {
	return &Process{Cmd: &exec.Cmd{Process: &os.Process{Pid: 1234}}, hooks: &processHooks{
		group:     func(pid int) (int, error) { return pid, nil },
		signal:    func(int, syscall.Signal) error { return nil },
		exited:    func() (bool, error) { return false, nil },
		wait:      func(time.Duration) (bool, error) { return true, nil },
		quiescent: func(int, time.Duration) error { return nil },
		reap:      func() error { return nil },
	}}
}

func removeMissing(p string) error {
	e := os.Remove(p)
	if os.IsNotExist(e) {
		return nil
	}
	return e
}
func CleanupOwnedSockets(vms map[string]*VM, dir string) []string {
	for _, v := range vms {
		if v.Process != nil {
			return []string{fmt.Sprintf("keep Firecracker API sockets until %s is confirmed stopped", v.Name)}
		}
	}
	errs := []string{}
	for _, v := range vms {
		if e := removeMissing(v.Socket); e != nil {
			errs = append(errs, fmt.Sprintf("remove owned Firecracker API socket %s: %v", v.Socket, e))
		}
	}
	if len(errs) > 0 {
		return errs
	}
	if e := removeMissing(dir); e != nil {
		errs = append(errs, fmt.Sprintf("remove empty Firecracker API socket directory %s: %v", dir, e))
	}
	return errs
}

func journalEntry(at time.Time, message string) string {
	return marshal(Object{"__REALTIME_TIMESTAMP": fmt.Sprint(at.UnixMicro()), "MESSAGE": message})
}

func parseSlog(message, event string, required []string) map[string]string {
	prefix := regexp.MustCompile(`^(\d{4}/\d{2}/\d{2} \d{2}:\d{2}:\d{2}) INFO ` + regexp.QuoteMeta(event) + `(?: (.*))?$`).FindStringSubmatch(message)
	if prefix == nil {
		return nil
	}
	if _, e := time.Parse("2006/01/02 15:04:05", prefix[1]); e != nil {
		return nil
	}
	parts, e := shellFields(prefix[2])
	if e != nil {
		return nil
	}
	fields := map[string]string{}
	for _, p := range parts {
		k, v, ok := strings.Cut(p, "=")
		if !ok || k == "" {
			return nil
		}
		if _, ok = fields[k]; ok {
			return nil
		}
		fields[k] = v
	}
	for _, k := range required {
		if _, ok := fields[k]; !ok {
			return nil
		}
	}
	return fields
}
func shellFields(s string) ([]string, error) {
	parts := []string{}
	var b strings.Builder
	quoteChar := rune(0)
	escaped := false
	active := false
	for _, c := range s {
		if escaped {
			b.WriteRune(c)
			escaped = false
			active = true
			continue
		}
		if c == '\\' && quoteChar != '\'' {
			escaped = true
			continue
		}
		if quoteChar != 0 {
			if c == quoteChar {
				quoteChar = 0
			} else {
				b.WriteRune(c)
			}
			active = true
			continue
		}
		if c == '\'' || c == '"' {
			quoteChar = c
			active = true
			continue
		}
		if c == ' ' || c == '\t' {
			if active {
				parts = append(parts, b.String())
				b.Reset()
				active = false
			}
			continue
		}
		active = true
		b.WriteRune(c)
	}
	if quoteChar != 0 || escaped {
		return nil, errors.New("malformed shell attributes")
	}
	if active {
		parts = append(parts, b.String())
	}
	return parts, nil
}

func ParseLeaseEvents(output string, since time.Time) []LeaseEvent {
	events := []LeaseEvent{}
	for line := range strings.SplitSeq(output, "\n") {
		v, e := decode(line)
		if e != nil {
			continue
		}
		entry := object(v)
		f := parseSlog(str(entry["MESSAGE"]), "host session accepted", []string{"phase", "session_id_hash", "epoch", "expires_at"})
		if f == nil {
			continue
		}
		micro, e := strconv.ParseInt(str(entry["__REALTIME_TIMESTAMP"]), 10, 64)
		if e != nil {
			continue
		}
		at := time.UnixMicro(micro)
		expiry, e := time.Parse(time.RFC3339Nano, f["expires_at"])
		if e != nil {
			continue
		}
		epoch, e := strconv.ParseInt(f["epoch"], 10, 64)
		if e != nil || epoch <= 0 || at.Before(since) || !regexp.MustCompile(`^[0-9a-f]{32}$`).MatchString(f["session_id_hash"]) {
			continue
		}
		events = append(events, LeaseEvent{at, expiry, f["session_id_hash"], f["phase"], epoch})
	}
	return events
}

func managedRuntimeLab(t *testing.T) *ManagedLab {
	t.Helper()
	root := t.TempDir()
	l := &ManagedLab{Ctx: t.Context(), Root: root, Commands: filepath.Join(root, "commands"), Images: filepath.Join(root, "images"), Mounts: filepath.Join(root, "mounts"), Fixture: filepath.Join(root, "fixture"), VMs: map[string]*ManagedVM{}, Mounted: map[string]bool{}}
