}

func (l *ManagedLab) Note(kind string, fields Object) {
	entry := Object{"at": time.Now().UTC().Format(time.RFC3339Nano), "kind": kind}
	for k, v := range fields {
		entry[k] = v
	}
	l.Events = append(l.Events, entry)
}
func (l *ManagedLab) RunCommand(label string, args []string, sudo bool, timeout time.Duration, allowed []int, env []string) (string, error) {
	l.CommandNumber++
	path := filepath.Join(l.Commands, fmt.Sprintf("%03d-%s.log", l.CommandNumber, label))
	argv := slices.Clone(args)
	if sudo {
		argv = append([]string{"sudo", "-n"}, argv...)
	}
	o := CommandOptions{Timeout: timeout, AllowFailure: true, Env: env}
	var r CommandResult
	var e error
	if l.Command != nil {
		r, e = l.Command(l.Ctx, argv, o)
		if writeErr := os.WriteFile(path, []byte(head(r.Stdout+r.Stderr, 32<<20)), 0o600); e == nil {
			e = writeErr
		}
		if len(r.Stdout+r.Stderr) > 32<<20 {
			e = errors.Join(e, errors.New("command log exceeded 33554432 bytes"))
		}
	} else {
		r, _, e = runBoundedCommand(l.Ctx, argv, o, path, 32<<20, l.commandHooks)
	}
	if pending, ok := errors.AsType[*PendingCommandError](e); ok {
		l.pendingCommands = append(l.pendingCommands, managedPendingCommand{label: label, path: path, process: pending.Process})
	}
	if e != nil {
		return "", fmt.Errorf("%s: %w; see %s", label, e, path)
	}
	if !slices.Contains(allowed, r.Code) {
		return "", fmt.Errorf("%s: exit %d; see %s: %s", label, r.Code, path, tail(r.Stdout, 1500))
	}
	l.Note("command", Object{"label": label, "argv": args, "sudo": sudo})
	return r.Stdout, nil
}
func (l *ManagedLab) cmd(label string, args []string, sudo bool, timeout time.Duration) (string, error) {
	return l.RunCommand(label, args, sudo, timeout, []int{0}, nil)
}

type BoundedWriter struct {
	mu           sync.Mutex
	File         *os.File
	Total, Limit int64
}

func (w *BoundedWriter) Write(b []byte) (int, error) {
	w.mu.Lock()
	defer w.mu.Unlock()
	remaining := max(int64(0), w.Limit-w.Total)
	w.Total += int64(len(b))
	if remaining > 0 {
		if _, e := w.File.Write(b[:min(int64(len(b)), remaining)]); e != nil {
			return 0, e
		}
	}
	return len(b), nil
}
func (w *BoundedWriter) Overflowed() bool { w.mu.Lock(); defer w.mu.Unlock(); return w.Total > w.Limit }
func (w *BoundedWriter) Close() error     { return w.File.Close() }
func BoundedCommand(ctx context.Context, argv []string, o CommandOptions, path string, bound int64) (CommandResult, error) {
	r, _, err := runBoundedCommand(ctx, argv, o, path, bound, nil)
	return r, err
}
func runBoundedCommand(ctx context.Context, argv []string, o CommandOptions, path string, bound int64, hooks *processHooks) (CommandResult, *Process, error) {
	if len(argv) == 0 {
		return CommandResult{}, nil, errors.New("empty command")
	}
	if err := ctx.Err(); err != nil {
		return CommandResult{}, nil, err
	}
	file, e := os.OpenFile(path, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0o600)
	if e != nil {
		return CommandResult{}, nil, e
	}
	capture := &BoundedWriter{File: file, Limit: bound}
	c := exec.Command(argv[0], argv[1:]...)
	c.Dir = o.Dir
	c.Env = o.Env
	c.Stdin = strings.NewReader(o.Input)
	c.Stdout = capture
	c.Stderr = capture
	c.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	c.WaitDelay = 2 * time.Second
	if e = c.Start(); e != nil {
		file.Close()
		return CommandResult{}, nil, e
	}
	p := &Process{Cmd: c, Output: capture, hooks: hooks}
	waitErr := waitCommand(ctx, p, o.Timeout)
	cleanup := p.Stop(10*time.Second, true)
	b, readErr := os.ReadFile(path)
	r := CommandResult{Code: p.ExitCode, Stdout: string(b)}
	if capture.Overflowed() {
		waitErr = errors.Join(waitErr, fmt.Errorf("command log exceeded %d bytes", bound))
	}
	if e = errors.Join(waitErr, cleanup, readErr); e != nil {
		if !p.Reaped {
			return r, p, &PendingCommandError{Process: p, Err: e}
		}
		return r, nil, e
	}
	if r.Code != 0 && !o.AllowFailure {
		return r, nil, fmt.Errorf("command failed (%d): %q; log: %s: %s", r.Code, argv, path, tail(r.Stdout, 1500))
	}
	return r, nil, nil
}

func CheckManagedSubnetCollision(ctx context.Context, command CommandFunc) error {
	subnet := netip.MustParsePrefix("10.77.39.0/24")
	for _, kind := range []string{"route", "addr"} {
		argv := []string{"ip", "-j", kind, "show"}
		if kind == "route" {
			argv = append(argv, "table", "all")
		}
		r, e := command(ctx, argv, CommandOptions{Timeout: 10 * time.Second})
		if e != nil {
			return e
		}
		v, e := decode(r.Stdout)
		if e != nil {
			return e
		}
		if kind == "route" {
			for _, row := range array(v) {
				s := str(object(row)["dst"])
				if s == "" || s == "default" {
					continue
				}
				p, e := netip.ParsePrefix(s)
				if e != nil {
					if a, e := netip.ParseAddr(s); e == nil {
						p = netip.PrefixFrom(a, a.BitLen())
					} else {
						continue
					}
				}
				if p.Overlaps(subnet) {
					return fmt.Errorf("fixture subnet collides with host route %s", s)
				}
			}
		} else {
			for _, row := range array(v) {
				for _, raw := range array(object(row)["addr_info"]) {
					a := object(raw)
					if a["family"] != "inet" {
						continue
					}
					p, e := netip.ParsePrefix(fmt.Sprintf("%s/%d", str(a["local"]), integer(a["prefixlen"])))
					if e != nil {
						return e
					}
					if p.Overlaps(subnet) {
						return fmt.Errorf("fixture subnet collides with host address %s", p.Masked())
					}
				}
			}
		}
	}
	return nil
}

func (l *ManagedLab) Network() error {
	command := l.Command
	if command == nil {
		command = Execute
	}
	if e := CheckManagedSubnetCollision(l.Ctx, command); e != nil {
		if pending, ok := errors.AsType[*PendingCommandError](e); ok {
			l.pendingCommands = append(l.pendingCommands, managedPendingCommand{label: "network-collision-probe", process: pending.Process})
		}
		return e
	}
	if e := l.createOwnedLink("bridge-add", l.Bridge, []string{"ip", "link", "add", "name", l.Bridge, "type", "bridge"}); e != nil {
		return e
	}
	for _, command := range []struct {
		label string
		args  []string
	}{{"bridge-address", []string{"ip", "addr", "add", "10.77.39.1/24", "dev", l.Bridge}}, {"bridge-up", []string{"ip", "link", "set", l.Bridge, "up"}}} {
		if _, e := l.cmd(command.label, command.args, true, 120*time.Second); e != nil {
			return e
		}
	}
	for _, member := range []string{"a", "b"} {
		tap := l.Taps[member]
		if e := l.createOwnedLink("tap-"+member+"-add", tap, []string{"ip", "tuntap", "add", "dev", tap, "mode", "tap", "user", strconv.Itoa(os.Getuid())}); e != nil {
			return e
		}
		for _, command := range []struct {
			label string
			args  []string
		}{{"tap-" + member + "-master", []string{"ip", "link", "set", tap, "master", l.Bridge}}, {"tap-" + member + "-up", []string{"ip", "link", "set", tap, "up"}}} {
			if _, e := l.cmd(command.label, command.args, true, 120*time.Second); e != nil {
				return e
			}
		}
	}
	l.Note("private_network", Object{"bridge": l.Bridge, "taps": l.Taps, "subnet": "10.77.39.0/24"})
	return nil
}

func (l *ManagedLab) linkExists(name string) (bool, error) {
	output, e := l.cmd("probe-"+name, []string{"ip", "-json", "link", "show"}, false, 30*time.Second)
	if e != nil {
		return false, e
	}
	var links []struct {
		Name string `json:"ifname"`
	}
	if e := json.Unmarshal([]byte(output), &links); e != nil {
		return false, fmt.Errorf("probe owned link %s: %w", name, e)
	}
	for _, link := range links {
		if link.Name == name {
			return true, nil
		}
	}
	return false, nil
}

func (l *ManagedLab) createOwnedLink(label, name string, argv []string) error {
	exists, e := l.linkExists(name)
	if e != nil {
		return e
	}
	if exists {
		return fmt.Errorf("private link name already exists: %s", name)
	}
	// Record the absent randomized name before dispatch: a canceled helper can
	// return after the kernel mutation, or remain pending until cleanup retries.
	l.CreatedLinks = append(l.CreatedLinks, name)
	_, e = l.cmd(label, argv, true, 120*time.Second)
	return e
}

func (l *ManagedLab) Cleanup() {
	original := l.Ctx
	l.Ctx = context.WithoutCancel(l.Ctx)
	defer func() { l.Ctx = original }()
	remaining := l.pendingCommands[:0]
	for _, pending := range l.pendingCommands {
		if e := pending.process.Stop(10*time.Second, true); e != nil && !pending.process.Reaped {
			l.CleanupErrors = append(l.CleanupErrors, fmt.Sprintf("stop pending command %s (log %s): %v", pending.label, pending.path, e))
			remaining = append(remaining, pending)
		} else if e != nil {
			l.CleanupErrors = append(l.CleanupErrors, fmt.Sprintf("finish pending command %s: %v", pending.label, e))
		}
	}
	l.pendingCommands = remaining
	for _, vm := range l.VMs {
		l.CleanupErrors = append(l.CleanupErrors, vm.Stop()...)
	}
	if len(l.pendingCommands) > 0 {
		l.CleanupErrors = append(l.CleanupErrors, "private network, images, mounts and fixture retained while commands may still be live")
		return
	}
	if l.RustFSStarted {
		_, e := l.RunCommand("rustfs-stop", []string{"podman", "rm", "--force", "--volumes", l.RustFSName}, false, 30*time.Second, []int{0, 1}, nil)
		if e == nil {
			_, e = l.RunCommand("rustfs-removed", []string{"podman", "container", "exists", l.RustFSName}, false, 10*time.Second, []int{1}, nil)
		}
		if e != nil {
			l.CleanupErrors = append(l.CleanupErrors, "remove RustFS fixture: "+e.Error())
		} else {
			l.RustFSStarted = false
		}
	}
	for member := range l.Mounted {
		if len(l.pendingCommands) > 0 {
			break
		}
		if e := l.UnmountRoot(member); e != nil {
			l.CleanupErrors = append(l.CleanupErrors, "unmount "+member+": "+e.Error())
		}
	}
	stopped := true
	for _, vm := range l.VMs {
		if !vm.Stopped {
			stopped = false
		}
	}
	if !stopped || l.RustFSStarted || len(l.pendingCommands) > 0 {
		l.CleanupErrors = append(l.CleanupErrors, "private network retained while a VM, RustFS or command may still be live")
	} else {
		for i := len(l.CreatedLinks) - 1; i >= 0; i-- {
			if len(l.pendingCommands) > 0 {
				break
			}
			link := l.CreatedLinks[i]
			exists, e := l.linkExists(link)
			if e != nil {
				l.CleanupErrors = append(l.CleanupErrors, "probe owned link "+link+": "+e.Error())
				continue
			}
			if !exists {
				l.CreatedLinks = slices.Delete(l.CreatedLinks, i, i+1)
				continue
			}
			if _, e := l.cmd("remove-"+link, []string{"ip", "link", "del", "dev", link}, true, 120*time.Second); e != nil {
				l.CleanupErrors = append(l.CleanupErrors, "remove owned link "+link+": "+e.Error())
			} else {
				l.CreatedLinks = slices.Delete(l.CreatedLinks, i, i+1)
			}
		}
	}
	if l.SocketDir != "" {
		if !stopped || len(l.pendingCommands) > 0 {
			l.CleanupErrors = append(l.CleanupErrors, "private API sockets retained while a VM may still be live")
		} else {
			entries, e := os.ReadDir(l.SocketDir)
			if e == nil {
				for _, entry := range entries {
					info, se := entry.Info()
					if se != nil {
						e = se
						break
					}
					if info.Mode()&os.ModeSocket == 0 || !slices.Contains([]string{"a.sock", "b.sock"}, entry.Name()) {
						e = fmt.Errorf("unexpected API socket entry %s", entry.Name())
						break
					}
					if e = os.Remove(filepath.Join(l.SocketDir, entry.Name())); e != nil {
						break
					}
				}
			}
			if e == nil {
				e = os.Remove(l.SocketDir)
			}
			if e != nil {
				l.CleanupErrors = append(l.CleanupErrors, "remove private API socket directory: "+e.Error())
			}
		}
	}
	if len(l.Mounted) == 0 && stopped && !l.RustFSStarted && len(l.pendingCommands) == 0 {
		for _, member := range []string{"a", "b"} {
			if e := removeMissing(filepath.Join(l.Images, member+"-rootfs.ext4")); e != nil {
				l.CleanupErrors = append(l.CleanupErrors, "remove private rootfs: "+e.Error())
			}
		}
		if l.Failure == "" && len(l.CleanupErrors) == 0 {
			for _, member := range []string{"a", "b"} {
				if e := removeMissing(filepath.Join(l.Images, member+"-volume.ext4")); e != nil {
					l.CleanupErrors = append(l.CleanupErrors, "remove private volume: "+e.Error())
				}
			}
		}
		l.Note("private_rootfs_removed", Object{})
	} else {
		l.CleanupErrors = append(l.CleanupErrors, "private rootfs with S3 credentials could not be removed")
	}
	if !l.RustFSStarted && len(l.pendingCommands) == 0 {
		if e := os.RemoveAll(l.Fixture); e != nil {
			l.CleanupErrors = append(l.CleanupErrors, "remove RustFS TLS and auth files: "+e.Error())
		}
	}
}

func (v *ManagedVM) Stop() []string {
	errs := []string{}
	if v.Process == nil {
		v.Stopped = true
		if e := v.finishCapture(); e != nil {
			errs = append(errs, e.Error())
		}
		return errs
	}
	if !v.Process.Reaped {
		if e := UnixAPI(context.WithoutCancel(v.Lab.Ctx), v.Socket, "/actions", Object{"action_type": "SendCtrlAltDel"}); e == nil {
			_, _ = v.Process.WaitUnreaped(15 * time.Second)
		}
		if e := v.Process.Stop(5*time.Second, false); e != nil {
			errs = append(errs, e.Error())
		}
		v.Stopped = v.Process.Reaped
	} else {
		v.Stopped = true
	}
	if v.Stopped {
		if e := v.finishCapture(); e != nil {
			errs = append(errs, e.Error())
		}
	}
	return errs
}

func ReadS3Credential(path string) (string, error) {
	if !filepath.IsAbs(path) {
		return "", errors.New("S3 credential path must be absolute")
	}
	before, e := os.Lstat(path)
	if e != nil {
		return "", e
	}
	fd, e := unix.Open(path, unix.O_RDONLY|unix.O_NOFOLLOW|unix.O_CLOEXEC|unix.O_NONBLOCK, 0)
	if e != nil {
		return "", e
	}
	f := os.NewFile(uintptr(fd), path)
	defer f.Close()
	info, e := f.Stat()
	if e != nil {
		return "", e
	}
	owner, ok := info.Sys().(*syscall.Stat_t)
	if !info.Mode().IsRegular() || !os.SameFile(before, info) || !ok || (owner.Uid != 0 && owner.Uid != uint32(os.Getuid())) || info.Mode().Perm() != 0o600 || info.Size() <= 0 || info.Size() > 1024 {
		return "", errors.New("S3 credential file has unsafe ownership, mode or size")
	}
	b, e := io.ReadAll(io.LimitReader(f, 1025))
	if e != nil {
		return "", e
	}
	after, e := f.Stat()
	if e != nil {
		return "", e
	}
	if int64(len(b)) != info.Size() || !after.ModTime().Equal(info.ModTime()) {
		return "", errors.New("S3 credential file changed while reading")
	}
	for _, c := range b {
		if c < 0x21 || c > 0x7e {
			return "", errors.New("S3 credential file contains invalid bytes")
		}
	}
	return string(b), nil
}
func S3Credentials(paths [2]string) ([2]string, error) {
	var values [2]string
	for i, p := range paths {
		v, e := ReadS3Credential(p)
		if e != nil {
			return values, e
		}
		if !regexp.MustCompile(`^[A-Za-z0-9_-]+$`).MatchString(v) {
			return values, errors.New("S3 fixture credentials must use ASCII letters, digits, '-' or '_'")
		}
		values[i] = v
	}
	return values, nil
}

func (l *ManagedLab) Install(mount, source, destination, mode, group string) error {
	target, e := GuestPath(mount, destination)
	if e != nil {
		return e
	}
	_, e = l.cmd("install-"+filepath.Base(destination), []string{"install", "-D", "-o", "root", "-g", group, "-m", mode, source, target}, true, 60*time.Second)
	return e
}
func (l *ManagedLab) InstallDir(mount, destination, mode, group string) error {
	target, e := GuestPath(mount, destination)
	if e != nil {
		return e
	}
	_, e = l.cmd("install-dir-"+filepath.Base(destination), []string{"install", "-d", "-o", "root", "-g", group, "-m", mode, target}, true, 30*time.Second)
	return e
}
func (l *ManagedLab) StagedSHA256(mount, destination string) (string, error) {
	target, e := GuestPath(mount, destination)
	if e != nil {
		return "", e
	}
	output, e := l.cmd("hash-"+filepath.Base(destination), []string{"sha256sum", target}, true, 60*time.Second)
	if e != nil {
		return "", e
	}
	fields := strings.Fields(output)
	if len(fields) != 2 || fields[1] != target || !shaPattern.MatchString(fields[0]) {
		return "", fmt.Errorf("staged guest hash output is malformed for %s", destination)
	}
	return fields[0], nil
}

func (l *ManagedLab) stageS3Credentials(mount, member string) error {
	keys, e := S3Credentials(l.S3CredentialPaths)
	if e != nil {
		return e
	}
	if l.S3KeyHashes != ([2]string{hashBytes([]byte(keys[0])), hashBytes([]byte(keys[1]))}) {
		return errors.New("S3 fixture credentials changed after RustFS startup")
	}
	for i, destination := range []string{"/etc/ts-managed-member/s3-access-key-id", "/etc/ts-managed-member/s3-secret-access-key"} {
		if e = l.Install(mount, l.S3CredentialPaths[i], destination, "0600", "root"); e != nil {
			return e
		}
		h, e := l.StagedSHA256(mount, destination)
		if e != nil {
			return e
		}
		if h != l.S3KeyHashes[i] {
			return fmt.Errorf("%s: staged S3 credential changed: %s", member, destination)
		}
		target, e := GuestPath(mount, destination)
		if e != nil {
			return e
		}
		if _, e = l.cmd(member+"-verify-"+filepath.Base(destination), []string{"cmp", "-s", "--", l.S3CredentialPaths[i], target}, true, 15*time.Second); e != nil {
			return e
		}
	}
	return nil
}

func GuestPath(mount, destination string) (string, error) {
	if !filepath.IsAbs(destination) || slices.Contains(strings.Split(destination, "/"), "..") {
		return "", fmt.Errorf("unsafe guest path %s", destination)
	}
	current := mount
	parts := strings.Split(strings.TrimPrefix(destination, "/"), "/")
	for i, part := range parts {
		if part == "" {
			continue
		}
		current = filepath.Join(current, part)
		s, e := os.Lstat(current)
		if os.IsNotExist(e) {
			continue
		}
		if e != nil {
			return "", e
		}
		if s.Mode()&os.ModeSymlink != 0 {
			return "", fmt.Errorf("guest path traverses symlink %s", current)
		}
		if i < len(parts)-1 && !s.IsDir() {
			return "", fmt.Errorf("guest path parent is not a directory: %s", current)
		}
	}
	return current, nil
}

func DirectDigest(path string) (string, error) {
	before, e := os.Lstat(path)
	if e != nil {
		return "", e
	}
	fd, e := unix.Open(path, unix.O_RDONLY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
	if e != nil {
		return "", e
	}
	f := os.NewFile(uintptr(fd), path)
	defer f.Close()
	opened, e := f.Stat()
	if e != nil {
		return "", e
	}
	if !opened.Mode().IsRegular() || !os.SameFile(before, opened) {
		return "", fmt.Errorf("file changed type or inode before hashing: %s", path)
	}
	b := make([]byte, 4<<20)
	h := sha256.New()
	if _, e = io.CopyBuffer(h, f, b); e != nil {
		return "", e
	}
	after, e := f.Stat()
	if e != nil {
		return "", e
	}
	afterPath, e := os.Lstat(path)
	if e != nil {
		return "", e
	}
	if !os.SameFile(opened, after) || !os.SameFile(after, afterPath) || opened.Size() != after.Size() || after.Size() != afterPath.Size() || !opened.ModTime().Equal(after.ModTime()) || !after.ModTime().Equal(afterPath.ModTime()) {
		return "", fmt.Errorf("file changed while hashing: %s", path)
	}
	return fmt.Sprintf("%x", h.Sum(nil)), nil
}

type ManagedInput struct {
	Path, SHA256 string
	Size         int64
}

func ExactManagedInput(name string, record Object) (ManagedInput, error) {
	if !exactFields(record, []string{"path", "sha256"}) {
		return ManagedInput{}, fmt.Errorf("%s: input must have exactly path and sha256", name)
	}
	path, expected := str(record["path"]), str(record["sha256"])
	if !filepath.IsAbs(path) || !shaPattern.MatchString(expected) {
		return ManagedInput{}, fmt.Errorf("%s: invalid absolute path or lowercase SHA-256", name)
	}
	s, e := os.Lstat(path)
	if e != nil {
		return ManagedInput{}, e
	}
	if !s.Mode().IsRegular() {
		return ManagedInput{}, fmt.Errorf("%s: input is not a regular, direct file", name)
	}
	h, e := DirectDigest(path)
	if e != nil {
		return ManagedInput{}, e
	}
	if h != expected {
		return ManagedInput{}, fmt.Errorf("%s: input SHA-256 mismatch: %s", name, path)
	}
	return ManagedInput{path, expected, s.Size()}, nil
}

func LoadManagedManifest(path string) (ManagedManifest, error) {
	var manifest ManagedManifest
	raw, e := os.ReadFile(path)
	if e != nil {
		return manifest, e
	}
	if len(raw) > 64<<10 {
		return manifest, errors.New("manifest exceeds 64 KiB")
	}
	v, e := decodeStrict(raw)
	if e != nil {
		return manifest, e
	}
	m := object(v)
	if !exactFields(m, []string{"profile", "source_commits", "inputs", "members"}) || m["profile"] != ManagedMemberProfile {
		return manifest, errors.New("unsupported or malformed qualification manifest")
	}
	commits := object(m["source_commits"])
	if !exactFields(commits, []string{"orchestrator", "terrabase"}) || !commitPattern.MatchString(str(commits["orchestrator"])) || !commitPattern.MatchString(str(commits["terrabase"])) {
		return manifest, errors.New("source commits must be full hexadecimal IDs")
	}
	common, members := object(m["inputs"]), object(m["members"])
	if !exactFields(common, ManagedCommonInputs) || !exactFields(members, []string{"a", "b"}) {
		return manifest, errors.New("manifest has missing or extra common/member inputs")
	}
	manifest = ManagedManifest{Raw: raw, SHA256: hashBytes(raw), Commits: commits, Inputs: map[string]ManagedInput{}, Members: map[string]ManagedMember{}}
	for _, name := range ManagedCommonInputs {
		input, e := ExactManagedInput(name, object(common[name]))
		if e != nil {
			return manifest, e
		}
		if slices.Contains([]string{"firecracker", "go_host_test", "tb_server"}, name) {
			if e := unix.Access(input.Path, unix.X_OK); e != nil {
				return manifest, fmt.Errorf("%s: input must be executable", name)
			}
		}
		manifest.Inputs[name] = input
	}

func (v *ManagedVM) Start() error {
	if len(v.Socket) >= 100 {
		return errors.New("Firecracker API socket path is too long")
	}
	var requests []FirecrackerRequest
	var e error
	if v.Resources != nil {
		requests, e = v.Resources()
	} else {
		requests, e = v.ResourceRequests()
	}
	if e != nil {
		return e
	}
	serial, e := os.OpenFile(filepath.Join(v.Lab.Logs, v.Member+"-serial.log"), os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0o600)
	if e != nil {
		return e
	}
	vmm, e := os.OpenFile(filepath.Join(v.Lab.Logs, v.Member+"-vmm.log"), os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0o600)
	if e != nil {
		serial.Close()
		return e
	}
	v.Serial = &BoundedWriter{File: serial, Limit: 32 << 20}
	v.VMM = &BoundedWriter{File: vmm, Limit: 32 << 20}
	c := exec.Command(v.Lab.Manifest.Inputs["firecracker"].Path, "--api-sock", v.Socket, "--log-path", "/dev/stderr")
	c.Stdout = v.Serial
	c.Stderr = v.VMM
	c.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	c.WaitDelay = 2 * time.Second
	if e = c.Start(); e != nil {
		return errors.Join(e, v.finishCapture())
	}
	v.Process = &Process{Cmd: c}
	deadline := time.Now().Add(20 * time.Second)
	for {
		if _, e = os.Stat(v.Socket); e == nil {
			break
		}
		done, e := v.Process.Exited()
		if e != nil {
			return e
		}
		if done {
			return fmt.Errorf("Firecracker %s exited before API socket", v.Member)
		}
		if time.Now().After(deadline) {
			return fmt.Errorf("Firecracker %s API socket timeout", v.Member)
		}
		select {
		case <-v.Lab.Ctx.Done():
			return v.Lab.Ctx.Err()
		case <-time.After(100 * time.Millisecond):
		}
	}
	requests = append([]FirecrackerRequest{{"/machine-config", Object{"vcpu_count": 2, "mem_size_mib": 6144, "smt": false}}, {"/boot-source", Object{"kernel_image_path": v.Lab.Manifest.Inputs["kernel"].Path, "boot_args": "console=ttyS0 reboot=k panic=-1 pci=off root=/dev/vda rw systemd.unit=multi-user.target"}}}, requests...)
	requests = append(requests, FirecrackerRequest{"/actions", Object{"action_type": "InstanceStart"}})
	for _, r := range requests {
		if e = UnixAPI(v.Lab.Ctx, v.Socket, r.Route, r.Body); e != nil {
			return e
		}
	}
	v.Lab.Note("vm_started", Object{"member": v.Member, "pid": v.Process.PID()})
	return nil
}
func (v *ManagedVM) finishCapture() error {
	var e error
	for _, capture := range []*BoundedWriter{v.Serial, v.VMM} {
		if capture != nil {
			if capture.Overflowed() {
				e = errors.Join(e, errors.New("VM output truncated or not drained"))
			}
			e = errors.Join(e, capture.Close())
		}
	}
	v.Serial, v.VMM = nil, nil
	return e
}

func (v *ManagedVM) Stop() []string {
	errs := []string{}
	if v.Process == nil {
		v.Stopped = true
		if e := v.finishCapture(); e != nil {
			errs = append(errs, e.Error())
		}
		return errs
	}
	if !v.Process.Reaped {
		if e := UnixAPI(context.WithoutCancel(v.Lab.Ctx), v.Socket, "/actions", Object{"action_type": "SendCtrlAltDel"}); e == nil {
			_, _ = v.Process.WaitUnreaped(15 * time.Second)
		}
		if e := v.Process.Stop(5*time.Second, false); e != nil {
			errs = append(errs, e.Error())
		}
		v.Stopped = v.Process.Reaped
	} else {
		v.Stopped = true
	}
	if v.Stopped {
		if e := v.finishCapture(); e != nil {
			errs = append(errs, e.Error())
		}
	}
	return errs
}

